"""Random values for count_set_bits.

The expected answer is captured from the reference rather than computed here,
so this only has to produce inputs worth running -- a spread of bit patterns,
including ones with the top bit set, where a signed shift would hang.
"""

MASK = 0xFFFFFFFF


def generate(rng, count):
    builders = (_scattered, _high_bits, _single_bit, _run_of_ones)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, value, description=""):
    return {"name": name, "stdin": "%d\n" % (value & MASK),
            "description": description}


def _scattered(rng, index):
    return _case("scattered bits #%d" % index, rng.randrange(1 << 32))


def _high_bits(rng, index):
    # Always has the top bit set, which is what separates shr from sar.
    return _case("top bit set #%d" % index,
                 (1 << 31) | rng.randrange(1 << 31),
                 "The top bit is set, so a signed shift would never "
                 "terminate.")


def _single_bit(rng, index):
    position = rng.randrange(32)
    return _case("one bit, at %d #%d" % (position, index), 1 << position)


def _run_of_ones(rng, index):
    width = rng.randint(1, 32)
    start = rng.randint(0, 32 - width)
    return _case("%d adjacent bits #%d" % (width, index),
                 ((1 << width) - 1) << start)
